import 'dart:async';

import 'package:flutter_bloc/flutter_bloc.dart';

import '../../../../core/resource.dart';
import '../../domain/entities/entry.dart';
import '../../domain/repositories/entries_repository.dart';

/// Drives `EntriesSearchBar`/`MeusRegistrosScreen`'s docked search surface
/// (spec-5-1) — the first real `Resource<T>` consumer (AD-12: "single data
/// source, single fetch" is exactly this screen's search slice, unlike
/// `MeusRegistrosState`'s own paginated shape). A DI `lazySingleton`
/// (Code Map), mirroring `MeusRegistrosCubit`: long-lived, so a query
/// already typed survives leaving and re-entering `/meus-registros` within
/// the same app session — though [onQueryChanged] is never called except
/// by the live `EntriesSearchBar`'s own `onChanged`, there is no
/// "re-run the last query on return" behavior to preserve here beyond the
/// cubit simply outliving the screen like `MeusRegistrosCubit` already
/// does.
class EntriesSearchCubit extends Cubit<Resource<List<Entry>>> {
  EntriesSearchCubit(this._repository) : super(const ResourceIdle());

  final EntriesRepository _repository;

  /// `EntriesSearchBar`'s own debounce window (I/O matrix: "5 keystrokes
  /// within 300ms -> exactly one `entries-search` call fires, for the
  /// final value").
  static const _debounceDuration = Duration(milliseconds: 300);

  Timer? _debounceTimer;

  /// A monotonic counter guarding against a stale in-flight [search] call's
  /// result landing after a newer one has already changed the state —
  /// mirrors `MeusRegistrosCubit._generation` exactly. Bumped both when a
  /// new debounced search actually starts *and* when the query is cleared
  /// back to idle (Boundaries' "Stale response" row: an in-flight query A
  /// must never land once query B — even an empty one — has already
  /// superseded it).
  int _generation = 0;

  /// `EntriesSearchBar.onChanged`'s one call site — [raw] is the text
  /// field's current (untrimmed) value on every keystroke. Cancels any
  /// pending debounce `Timer` first, regardless of outcome below (Code
  /// Map/Boundaries): a keystroke always supersedes whatever this cubit
  /// was about to do next.
  void onQueryChanged(String raw) {
    _debounceTimer?.cancel();
    final query = raw.trim();
    if (query.isEmpty) {
      // I/O matrix: "Query cleared" — no request, pending work discarded,
      // timeline shown. Bumping the generation here (not only inside
      // [_search]) is what actually discards an already-in-flight
      // previous query's result once it resolves.
      _generation++;
      // Review finding: `close()` can race this synchronous call too (a
      // fast app teardown landing between a keystroke and this handler) —
      // same `isClosed` rationale `_search`'s own guard below already
      // documents; `emit()` after `close()` would otherwise throw.
      if (isClosed) {
        return;
      }
      emit(const ResourceIdle());
      return;
    }
    _debounceTimer = Timer(_debounceDuration, () => _search(query));
  }

  Future<void> _search(String query) async {
    final generation = ++_generation;
    // Review finding: deliberately *not* `const` — `ResourceLoading<T>`
    // has no custom `==`, so `const ResourceLoading()` is a canonicalized
    // singleton instance. Two searches in a row (e.g. "an" still in
    // flight when "ans" debounces) would otherwise both emit that exact
    // same instance; `Cubit.emit` (package:bloc) skips re-emitting a state
    // `==` to the current one, so the second transition into loading
    // would silently no-op — `MeusRegistrosScreen._onSearchStateChanged`'s
    // listener never re-fires, and its 300ms skeleton timer never resets
    // for "ans", measuring RNF01's threshold from the wrong start time. A
    // fresh (non-const) instance is identity-distinct from the prior one
    // even though both are `ResourceLoading`, so `emit` always proceeds.
    emit(ResourceLoading());
    final result = await _repository.search(query);
    // Mirrors `MeusRegistrosCubit.loadFirstPage`'s own guard: `close()` can
    // race this awaited call, and a newer query (or a clear back to idle)
    // can have superseded this one while it was in flight.
    if (isClosed || generation != _generation) {
      return;
    }
    result.match(
      (failure) => emit(ResourceError(failure)),
      (entries) => emit(ResourceData(entries)),
    );
  }

  @override
  Future<void> close() {
    _debounceTimer?.cancel();
    return super.close();
  }
}

import 'package:fpdart/fpdart.dart';

import '../../../../core/failure/failure.dart';
import '../entities/entries_page.dart';
import '../entities/entry.dart';

/// The port later epics extend (Code Map) — `features/capture/` depends on
/// this abstract class only, never `entries/data` or `entries/presentation`
/// (RNF06).
abstract class EntriesRepository {
  /// Posts to `entries-create` (`ApiClient.post`, via
  /// `EntriesRemoteDataSource`) and, on success, writes the entry through
  /// to the `entries` Hive box before returning `Right` (Boundaries) — a
  /// caller that only reads the returned [Entry] never needs to touch the
  /// box itself. Every [Failure] — including
  /// [Failure.networkOffline] — is returned as `Left`, unmapped and
  /// un-retried; the caller decides what to do with it (RNF09).
  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
    int? mediaDurationSeconds,
  });

  /// Calls `entries-list` (`ApiClient.get`, via
  /// `EntriesRemoteDataSource`), newest-first by `occurredAt` — server
  /// behavior assumed, undocumented (Code Map, decided per AGENTS.md
  /// policy: "where `docs/input/` is silent... decide and proceed").
  ///
  /// spec-5-2 — [source]/[dateFrom]/[dateTo] are forwarded to
  /// `entries-list` as its own `source`/`dateFrom`/`dateTo` query
  /// parameters (`EntriesRemoteDataSource.list()`'s own doc), each only
  /// when non-null; combining more than one narrows with AND logic (the
  /// backend's own semantics, RF06 Acceptance Criteria) — this repository
  /// does no client-side filtering/joining of its own (AD-9).
  ///
  /// On [Failure.networkOffline]/[Failure.networkTimeout] specifically,
  /// falls back to a full dump of the `entries` Hive box, sorted
  /// `occurredAt` desc, with `EntriesPage.nextCursor: null` (Boundaries) —
  /// every *other* [Failure] (e.g. [Failure.authExpired]) propagates as
  /// `Left`, unmapped (RNF09). That fallback (`cursor == null` only) stays
  /// filter-oblivious regardless of [source]/[dateFrom]/[dateTo] — AD-9:
  /// the cache is never locally filtered, so an offline first page always
  /// renders the full cached list even with filters active.
  ///
  /// A successful page persists every item to the `entries` Hive box
  /// *before* returning `Right` — same "persist then return" ordering
  /// [create] already uses.
  Future<Either<Failure, EntriesPage>> list({
    String? cursor,
    int limit = 20,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
  });

  /// spec-4-4 (RF07) — calls `entries-get` (`ApiClient.get`, via
  /// `EntriesRemoteDataSource`) with [id] as the one path parameter, then
  /// persists the fetched entry to the `entries` Hive box (`put`) *before*
  /// returning `Right` — same "persist then return" ordering
  /// [create]/[list] already use. AD-11 keeps this port create+read-only,
  /// not count-capped — [search] (spec-5-1) added a fourth method without
  /// contradicting that.
  ///
  /// On [Failure.networkOffline]/[Failure.networkTimeout] specifically,
  /// falls back to `entriesBox.get(id)` if present; a cache miss propagates
  /// the original failure unchanged (no synthesized not-found — that
  /// distinction belongs to whichever `Failure` the backend/network
  /// actually produced). Every *other* [Failure] — including
  /// [Failure.notFound] for an id that never existed or belongs to another
  /// user — is returned as `Left`, unmapped (RNF09); RNF04 (identical
  /// treatment for both causes) is the caller's own rendering job, never
  /// this repository's.
  Future<Either<Failure, Entry>> getById(String id);

  /// spec-5-1 — calls `entries-search` (`ApiClient.get`, via
  /// `EntriesRemoteDataSource`) with [query] as the one `q` query
  /// parameter (no `limit`/`cursor` — Boundaries). [query] is always
  /// already a non-empty, pre-trimmed string by the time it reaches this
  /// method — `EntriesSearchCubit` owns that guarantee, never this
  /// repository.
  ///
  /// On success, persists every returned entry to the `entries` Hive box
  /// (`putAll`) *before* returning `Right` — same "persist then return"
  /// ordering [list]/[getById] already use. Unlike [list]/[getById], there
  /// is no offline/timeout cache fallback here (AD-9: no client-side
  /// vector index) — every [Failure], including
  /// [Failure.networkOffline], is returned as `Left`, unmapped (RNF09).
  Future<Either<Failure, List<Entry>>> search(String query);
}

