755	                color: DesignTokens.colorCategoryChipText,
756	              ),
757	            ],
758	          ),
759	        ),
760	      ),
761	    );
762	  }
763	}
764	
765	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
766	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
767	/// always already truncated to local midnight (`EntryDateGroup`'s own
768	/// contract).
769	String _dayLabel(DateTime date) {
770	  final now = DateTime.now();
771	  final today = DateTime(now.year, now.month, now.day);
772	  final yesterday = today.subtract(const Duration(days: 1));
773	  if (date == today) {
774	    return 'Hoje';
775	  }
776	  if (date == yesterday) {
777	    return 'Ontem';
778	  }
779	  final day = date.day.toString().padLeft(2, '0');
780	  final month = date.month.toString().padLeft(2, '0');
781	  return '$day/$month/${date.year}';
782	}
