import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:go_router/go_router.dart';

import '../../../../core/design_tokens.dart';
import '../../../../core/di/injection_container.dart';
import '../../../../core/navigation/app_route_paths.dart';
import '../../../../core/resource.dart';
import '../../../../core/widgets/app_button.dart';
import '../../../../core/widgets/back_arrow_header.dart';
import '../../../capture/presentation/cubit/audio_entry_cubit.dart';
import '../../../capture/presentation/cubit/photo_entry_cubit.dart';
import '../../../capture/presentation/cubit/text_entry_cubit.dart';
import '../../../capture/presentation/widgets/insertion_modal.dart';
import '../../domain/entities/entry.dart';
import '../../domain/entities/entry_date_group.dart';
import '../../domain/entities/sync_badge_state.dart';
import '../cubit/entries_search_cubit.dart';
import '../cubit/meus_registros_cubit.dart';
import '../cubit/meus_registros_state.dart';
import '../widgets/entries_filter_sheet.dart';
import '../widgets/entries_search_bar.dart';
import '../widgets/entry_record_card.dart';
import '../widgets/entry_skeleton_card.dart';

/// Tela 4 — Meus Registros, spec-4-1's real build: every `Entry`,
/// newest-first, grouped by day, each card marked by origin. Replaces the
/// former `MeusRegistrosPlaceholderScreen`.
///
/// [cubit] is a DI `lazySingleton` (Code Map) — this `StatefulWidget` never
/// closes it (`BlocProvider.value`, same convention
/// `AccountSettingsScreen` already uses for its own singleton cubit); only
/// this screen's own [ScrollController] is this `State`'s to dispose.
///
/// The global `ExpiryOverlayHost` shows its "Sessão expirada" dialog via
/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
/// rebuilt from scratch underneath it, so [_scrollController]'s position
/// and [cubit]'s state survive that overlay appearing with no extra code
/// needed here (Acceptance Criteria's third bullet).
class MeusRegistrosScreen extends StatefulWidget {
  const MeusRegistrosScreen({
    required this.cubit,
    required this.searchCubit,
    super.key,
  });

  final MeusRegistrosCubit cubit;

  /// spec-5-1 — the permanently-docked `EntriesSearchBar`'s own cubit, a DI
  /// `lazySingleton` like [cubit] (Code Map); this `StatefulWidget` never
  /// closes it either, same rationale [cubit]'s own doc above gives.
  final EntriesSearchCubit searchCubit;

  @override
  State<MeusRegistrosScreen> createState() => _MeusRegistrosScreenState();
}

class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
  // `BootSplashScreen`.
  static const _skeletonThreshold = Duration(milliseconds: 300);

  final ScrollController _scrollController = ScrollController();
  Timer? _skeletonTimer;
  bool _showSkeleton = false;

  /// spec-5-1 — the search surface's own 300ms skeleton threshold,
  /// mirroring [_skeletonTimer]/[_showSkeleton] above but keyed off
  /// `EntriesSearchCubit`'s `ResourceLoading` rather than
  /// `MeusRegistrosLoading`: started fresh on every transition into
  /// `ResourceLoading` (`_onSearchStateChanged` below), since unlike the
  /// first-load timer above (started once, in [initState]) a search can
  /// enter/leave loading many times across one screen visit.
  Timer? _searchSkeletonTimer;
  bool _showSearchSkeleton = false;

  /// Review fix (round 2, spec-4-4) — guards `_openDetail` against a rapid
  /// double-tap on a card pushing `/meus-registros/:id` twice (stacking two
  /// detail-route instances); cleared once the pushed route is popped, via
  /// `whenComplete` below.
  bool _navigatingToDetail = false;

  @override
  void initState() {
    super.initState();
    widget.cubit.loadFirstPage();
    _skeletonTimer = Timer(_skeletonThreshold, () {
      if (mounted) {
        setState(() => _showSkeleton = true);
      }
    });
    _scrollController.addListener(_onScroll);
    // Review finding: `searchCubit` is a long-lived singleton (Code Map)
    // that can already be `ResourceLoading` the moment this `State` is
    // (re)created — e.g. the user switches tabs away mid-search and back,
    // which tears down and rebuilds this plain `GoRoute`'s widget while the
    // DI-singleton cubit keeps running. `BlocConsumer`'s `listener` below
    // only fires on a *new* state, never for one already current at
    // subscription time, so without this check the search skeleton would
    // never arm for an in-flight search resumed this way.
    if (widget.searchCubit.state is ResourceLoading<List<Entry>>) {
      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
        if (mounted) {
          setState(() => _showSearchSkeleton = true);
        }
      });
    }
  }

  @override
  void dispose() {
    _skeletonTimer?.cancel();
    _searchSkeletonTimer?.cancel();
    _scrollController
      ..removeListener(_onScroll)
      ..dispose();
    super.dispose();
  }

  /// `BlocConsumer<EntriesSearchCubit, ...>`'s own listener (below) — starts
  /// [_searchSkeletonTimer] fresh on every transition into
  /// `ResourceLoading`, mirroring [initState]'s one-shot [_skeletonTimer]
  /// but re-armed per search rather than once per screen visit; any other
  /// state (including a fast resolve before the 300ms threshold, RNF01)
  /// cancels it and resets [_showSearchSkeleton].
  void _onSearchStateChanged(
    BuildContext context,
    Resource<List<Entry>> state,
  ) {
    _searchSkeletonTimer?.cancel();
    if (state is ResourceLoading<List<Entry>>) {
      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
        if (mounted) {
          setState(() => _showSearchSkeleton = true);
        }
      });
      return;
    }
    if (_showSearchSkeleton) {
      setState(() => _showSearchSkeleton = false);
    }
  }

  void _openDetail(Entry entry) {
    if (_navigatingToDetail) {
      return;
    }
    _navigatingToDetail = true;
    context
        .push(
          '${AppRoutePaths.meusRegistros}/'
          '${Uri.encodeComponent(entry.id)}',
        )
        .whenComplete(() {
          if (mounted) {
            setState(() => _navigatingToDetail = false);
          } else {
            _navigatingToDetail = false;
          }
        });
  }

  void _onScroll() {
    if (!_scrollController.hasClients) {
      return;
    }
    final position = _scrollController.position;
    // Pre-fetches a little before the exact end (reusing `spacing2xl`
    // purely as a scroll-distance buffer, not a new literal) for a
    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
    // there's no further page or a call is already in flight.
    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
      widget.cubit.loadMore();
    }
  }

  @override
  Widget build(BuildContext context) {
    return MultiBlocProvider(
      providers: [
        BlocProvider.value(value: widget.cubit),
        BlocProvider.value(value: widget.searchCubit),
      ],
      child: Scaffold(
        backgroundColor: DesignTokens.colorSurfaceBg,
        body: Column(
          children: [
            const BackArrowHeader(title: 'Meus Registros'),
            Padding(
              padding: const EdgeInsets.fromLTRB(
                DesignTokens.spacingMd,
                DesignTokens.spacingMd,
                DesignTokens.spacingMd,
                0,
              ),
              // spec-5-2: `hasActiveFilters`/`onFilterTap` need the real
              // `MeusRegistrosCubit` — this now rebuilds on its state too,
              // while `EntriesSearchBar` itself stays a dumb, stateless
              // widget, same as before. Also rebuilds on `EntriesSearchCubit`
              // (code-review fix): the funnel must only read as "filled"
              // while the plain/filtered timeline is actually what's on
              // screen — filters+search integration is 5.3's job, out of
              // this story's scope, so "filled" next to search results
              // that were never filtered would be misleading.
              child: BlocBuilder<EntriesSearchCubit, Resource<List<Entry>>>(
                builder: (context, searchState) =>
                    BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
                      builder: (context, _) => EntriesSearchBar(
                        onChanged: widget.searchCubit.onQueryChanged,
                        onFilterTap: () => EntriesFilterSheet.show(
                          context,
                          cubit: widget.cubit,
                        ),
                        hasActiveFilters:
                            searchState is ResourceIdle<List<Entry>> &&
                            widget.cubit.hasActiveFilters,
                      ),
                    ),
              ),
            ),
            Expanded(
              child: BlocConsumer<EntriesSearchCubit, Resource<List<Entry>>>(
                listener: _onSearchStateChanged,
                builder: (context, searchState) {
                  // Boundaries: "an empty query reverts to the normal
                  // timeline" — `ResourceIdle` is the only variant that
                  // falls through to the pre-existing
                  // `MeusRegistrosCubit`-driven timeline below; every other
                  // variant renders the search surface instead.
                  if (searchState is ResourceIdle<List<Entry>>) {
                    return BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
                      builder: (context, state) {
                        final timeline = switch (state) {
                          MeusRegistrosLoading() =>
                            _showSkeleton
                                ? const _SkeletonList()
                                : const SizedBox.shrink(),
                          MeusRegistrosEmpty() => const _EmptyState(),
                          MeusRegistrosError(message: final message) =>
                            _ErrorState(
                              message: message,
                              // Code-review fix: `retryCurrentPage()`, not
                              // `loadFirstPage()` — the latter resets the
                              // active filter selection, silently turning
                              // a failed *filtered* retry into a
                              // successful unfiltered one.
                              onRetry: widget.cubit.retryCurrentPage,
                            ),
                          MeusRegistrosLoaded() => _EntryList(
                            state: state,
                            scrollController: _scrollController,
                            onRetryLoadMore: widget.cubit.retryLoadMore,
                            onRetryTap: (entry) => widget.cubit.retry(entry.id),
                            onCardTap: _openDetail,
                          ),
                        };
                        // spec-5-2: the active-filter chip row only ever
                        // renders here, inside the plain-timeline branch
                        // (Boundaries/Never: no combined search+filter
                        // query this story) — and only once a filter is
                        // actually active.
                        if (!widget.cubit.hasActiveFilters) {
                          return timeline;
                        }
                        return Column(
                          children: [
                            _ActiveFiltersRow(cubit: widget.cubit),
                            Expanded(child: timeline),
                          ],
                        );
                      },
                    );
                  }
                  return _SearchResults(
                    state: searchState,
                    showSkeleton: _showSearchSkeleton,
                    onCardTap: _openDetail,
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

/// spec-5-1's own search-results surface — `EntriesSearchCubit`'s
/// `Resource<List<Entry>>` rendered in place of the timeline whenever
/// [state] isn't `ResourceIdle` (the screen's own `build` filters that
/// variant out before ever reaching here). Every result here is always a
/// server-confirmed [Entry] (`EntriesRepository.search()`'s own contract —
/// no cache fallback, no pending-write overlay), so every card's badge is
/// unconditionally [SyncBadgeState.synchronized] — never recomputed via
/// `deriveSyncBadgeState()` (Never: "any screen recomputing badge state
/// inline" extends here too, there is simply no pending/offline state for
/// a search result to derive).
class _SearchResults extends StatelessWidget {
  const _SearchResults({
    required this.state,
    required this.showSkeleton,
    required this.onCardTap,
  });

  final Resource<List<Entry>> state;
  final bool showSkeleton;
  final void Function(Entry entry) onCardTap;

  @override
  Widget build(BuildContext context) {
    return switch (state) {
      ResourceIdle<List<Entry>>() =>
        // Unreachable — `MeusRegistrosScreen.build` never routes
        // `ResourceIdle` here — kept only so this switch stays exhaustive.
        const SizedBox.shrink(),
      ResourceLoading<List<Entry>>() =>
        showSkeleton ? const _SkeletonList() : const SizedBox.shrink(),
      ResourceError<List<Entry>>(failure: final failure) => _SearchErrorState(
        message: failure.message,
      ),
      ResourceData<List<Entry>>(data: final entries) =>
        entries.isEmpty
            ? const _EmptySearchResults()
            : ListView.builder(
                padding: DesignTokens.screenPadding,
                itemCount: entries.length,
                itemBuilder: (context, index) {
                  final entry = entries[index];
                  return Padding(
                    key: ValueKey(entry.id),
                    padding: const EdgeInsets.only(
                      bottom: DesignTokens.spacingSm,
                    ),
                    child: EntryRecordCard(
                      entry: entry,
                      badgeState: const SyncBadgeState.synchronized(),
                      onTap: () => onCardTap(entry),
                    ),
                  );
                },
              ),
    };
  }
}

/// `ResourceError<List<Entry>>`'s own rendering (spec-5-1 I/O matrix:
/// "ResourceError(networkOffline) rendered") — just the message, unlike
/// [_ErrorState] above: there is no retry affordance named for search
/// anywhere in Boundaries/the I/O matrix, since the user's own next
/// keystroke (re-debounced through `EntriesSearchCubit`) is what retries,
/// never an explicit button.
class _SearchErrorState extends StatelessWidget {
  const _SearchErrorState({required this.message});

  final String message;

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Padding(
        padding: DesignTokens.screenPadding,
        child: Text(
          message,
          textAlign: TextAlign.center,
          style: DesignTokens.textBodyMd.copyWith(
            color: DesignTokens.colorTextPrimary,
          ),
        ),
      ),
    );
  }
}

class _EmptySearchResults extends StatelessWidget {
  const _EmptySearchResults();

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Padding(
        padding: DesignTokens.screenPadding,
        child: Text(
          'Nenhum resultado encontrado',
          textAlign: TextAlign.center,
          style: DesignTokens.textBodyMd.copyWith(
            color: DesignTokens.colorTextSecondary,
          ),
        ),
      ),
    );
  }
}

class _SkeletonList extends StatelessWidget {
  const _SkeletonList();

  // Not a real count of anything server-sent — just enough placeholder
  // cards to fill a typical screen while the first page is in flight.
  static const _placeholderCount = 4;

  @override
  Widget build(BuildContext context) {
    return ListView.builder(
      padding: DesignTokens.screenPadding,
      itemCount: _placeholderCount,
      itemBuilder: (context, index) => Padding(
        padding: const EdgeInsets.only(bottom: DesignTokens.spacingSm),
        child: const EntrySkeletonCard(),
      ),
    );
  }
}

class _EmptyState extends StatelessWidget {
  const _EmptyState();

  @override
  Widget build(BuildContext context) {
    // Tela 4 — Vazio: icon + copy + a primary CTA that opens the same
    // Insertion Modal the Home/Chat "+" FAB opens (`placeholder_screens.
    // dart`'s own call shape, mirrored verbatim) — spec-4-3.
    return Center(
      child: Padding(
        padding: const EdgeInsets.symmetric(
          vertical: DesignTokens.entriesEmptyStateVerticalPadding,
          horizontal: DesignTokens.spacingLg,
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(
              Icons.menu_book_outlined,
              size: DesignTokens.entriesEmptyStateIconSize,
              color: DesignTokens.colorBorder,
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            Text(
              'Nenhum registro ainda',
              style: DesignTokens.textBodyMd.copyWith(
                color: DesignTokens.colorTextSecondary,
              ),
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            AppButton(
              label: 'Criar primeiro registro',
              onPressed: () => InsertionModal.show(
                context,
                cubit: sl<TextEntryCubit>(),
                audioCubit: sl<AudioEntryCubit>(),
                photoCubit: sl<PhotoEntryCubit>(),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _ErrorState extends StatelessWidget {
  const _ErrorState({required this.message, required this.onRetry});

  final String message;
  final VoidCallback onRetry;

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Padding(
        padding: DesignTokens.screenPadding,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              message,
              textAlign: TextAlign.center,
              style: DesignTokens.textBodyMd.copyWith(
                color: DesignTokens.colorTextPrimary,
              ),
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            TextButton(
              onPressed: onRetry,
              child: Text(
                'Tentar novamente',
                style: DesignTokens.textLabelMd.copyWith(
                  color: DesignTokens.colorPrimary,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _EntryList extends StatelessWidget {
  const _EntryList({
    required this.state,
    required this.scrollController,
    required this.onRetryLoadMore,
    required this.onRetryTap,
    required this.onCardTap,
  });

  final MeusRegistrosLoaded state;
  final ScrollController scrollController;
  final VoidCallback onRetryLoadMore;
  final void Function(Entry entry) onRetryTap;

  /// spec-4-4 — opens `EntryDetailScreen` for the tapped card.
  final void Function(Entry entry) onCardTap;

  @override
  Widget build(BuildContext context) {
    final groups = state.groups;
    // A non-empty `state.entries` can still yield zero groups if every one
    // of its `occurredAt` values is malformed (`groupEntriesByDate()` skips
    // rather than throws) — fall back to the same plain empty-state text
    // rather than rendering a ListView with nothing visibly in it.
    if (groups.isEmpty) {
      return const _EmptyState();
    }
    return ListView.builder(
      controller: scrollController,
      padding: DesignTokens.screenPadding,
      itemCount: groups.length + 1,
      itemBuilder: (context, index) {
        if (index == groups.length) {
          return _LoadMoreFooter(
            hasMore: state.nextCursor != null,
            isLoading: state.isLoadingMore,
            failed: state.loadMoreFailed,
            onRetry: onRetryLoadMore,
          );
        }
        return _DateGroupSection(
          group: groups[index],
          badgeFor: state.badgeFor,
          onRetryTap: onRetryTap,
          onCardTap: onCardTap,
        );
      },
    );
  }
}

class _DateGroupSection extends StatelessWidget {
  const _DateGroupSection({
    required this.group,
    required this.badgeFor,
    required this.onRetryTap,
    required this.onCardTap,
  });

  final EntryDateGroup group;

  /// `MeusRegistrosLoaded.badgeFor` — the one call site outside the
  /// cubit/state itself (Never: "any screen recomputing badge state
  /// inline").
  final SyncBadgeState Function(Entry entry) badgeFor;

  /// `MeusRegistrosCubit.retry`, pre-bound to this entry's own id —
  /// `EntryRecordCard`/`SyncBadge` only ever call this for a retryable
  /// error badge.
  final void Function(Entry entry) onRetryTap;

  /// spec-4-4 — `EntryRecordCard`'s own `onTap`, pre-bound to this entry's
  /// own id.
  final void Function(Entry entry) onCardTap;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.only(bottom: DesignTokens.spacingMd),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            _dayLabel(group.date),
            style: DesignTokens.textTitleSm.copyWith(
              color: DesignTokens.colorTextPrimary,
            ),
          ),
          const SizedBox(height: DesignTokens.spacingSm),
          for (final entry in group.entries) ...[
            EntryRecordCard(
              key: ValueKey(entry.id),
              entry: entry,
              badgeState: badgeFor(entry),
              onTap: () => onCardTap(entry),
              onRetryTap: () => onRetryTap(entry),
            ),
            const SizedBox(height: DesignTokens.spacingSm),
          ],
        ],
      ),
    );
  }
}

class _LoadMoreFooter extends StatelessWidget {
  const _LoadMoreFooter({
    required this.hasMore,
    required this.isLoading,
    required this.failed,
    required this.onRetry,
  });

  final bool hasMore;
  final bool isLoading;
  final bool failed;
  final VoidCallback onRetry;

  @override
  Widget build(BuildContext context) {
    if (failed) {
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: DesignTokens.spacingMd),
        child: Center(
          child: TextButton(
            onPressed: onRetry,
            child: Text(
              'Tentar novamente',
              style: DesignTokens.textLabelMd.copyWith(
                color: DesignTokens.colorPrimary,
              ),
            ),
          ),
        ),
      );
    }
    if (isLoading) {
      return const Padding(
        padding: EdgeInsets.symmetric(vertical: DesignTokens.spacingMd),
        child: Center(
          child: CircularProgressIndicator(color: DesignTokens.colorPrimary),
        ),
      );
    }
    return const SizedBox.shrink();
  }
}

/// spec-5-2 — the active-filter chip row rendered under the search bar
/// whenever `MeusRegistrosCubit.hasActiveFilters` is true (Boundaries);
/// reads the cubit's own filter fields directly rather than threading them
/// through `MeusRegistrosState` (Design Notes: a filter change already
/// re-emits a new state via `applyFilters()`/`clearFilters()`, so this
/// widget's own `BlocBuilder` ancestor already rebuilds it in lockstep).
class _ActiveFiltersRow extends StatelessWidget {
  const _ActiveFiltersRow({required this.cubit});

  final MeusRegistrosCubit cubit;

  @override
  Widget build(BuildContext context) {
    final source = cubit.activeSource;
    final dateFrom = cubit.activeDateFrom;
    final dateTo = cubit.activeDateTo;
    final dateRangePreset = cubit.activeDateRangePreset;
    final hasDateRange = dateFrom != null && dateTo != null;
    return Padding(
      padding: const EdgeInsets.fromLTRB(
        DesignTokens.spacingMd,
        DesignTokens.spacingSm,
        DesignTokens.spacingMd,
        0,
      ),
      child: Wrap(
        crossAxisAlignment: WrapCrossAlignment.center,
        spacing: DesignTokens.spacingSm,
        runSpacing: DesignTokens.spacingSm,
        children: [
          if (source != null)
            _ActiveFilterChip(
              label: entrySourceLabel(source),
              // I/O matrix: "Remove one of two active chips" — re-applies
              // every *other* active filter exactly as it stood, dropping
              // only this one. Round-2 review fix: passes `dateRangePreset`
              // back in too — otherwise the still-active date range would
              // revert to the cubit's default "Todo o período" preset.
              onRemove: () => cubit.applyFilters(
                dateFrom: dateFrom,
                dateTo: dateTo,
                dateRangePreset: dateRangePreset,
              ),
            ),
          if (hasDateRange)
            _ActiveFilterChip(
              label: dateRangePresetLabel(dateRangePreset),
              onRemove: () => cubit.applyFilters(source: source),
            ),
          AppButton(
            variant: AppButtonVariant.textGhost,
            label: 'Limpar filtros',
            // I/O matrix: "Clear all filters" — restores the full
            // unfiltered list in place, no reload/re-mount (Boundaries).
            onPressed: cubit.clearFilters,
          ),
        ],
      ),
    );
  }
}

/// One removable active-filter chip — `colorSecondary`/
/// `colorCategoryChipText`/`radiusFull` (Boundaries: exact token reuse,
/// no new token).
class _ActiveFilterChip extends StatelessWidget {
  const _ActiveFilterChip({required this.label, required this.onRemove});

  final String label;
  final VoidCallback onRemove;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      button: true,
      label: '$label, remover filtro',
      excludeSemantics: true,
      child: InkWell(
        borderRadius: const BorderRadius.all(
          Radius.circular(DesignTokens.radiusFull),
        ),
        onTap: onRemove,
        child: Container(
          padding: const EdgeInsets.symmetric(
            horizontal: DesignTokens.spacingMd,
            vertical: DesignTokens.spacingXs,
          ),
          decoration: const BoxDecoration(
            color: DesignTokens.colorSecondary,
            borderRadius: BorderRadius.all(
              Radius.circular(DesignTokens.radiusFull),
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                label,
                style: DesignTokens.textLabelMd.copyWith(
                  color: DesignTokens.colorCategoryChipText,
                ),
              ),
              const SizedBox(width: DesignTokens.spacingXs),
              const Icon(
                Icons.close,
                color: DesignTokens.colorCategoryChipText,
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
/// always already truncated to local midnight (`EntryDateGroup`'s own
/// contract).
String _dayLabel(DateTime date) {
  final now = DateTime.now();
  final today = DateTime(now.year, now.month, now.day);
  final yesterday = today.subtract(const Duration(days: 1));
  if (date == today) {
    return 'Hoje';
  }
  if (date == yesterday) {
    return 'Ontem';
  }
  final day = date.day.toString().padLeft(2, '0');
  final month = date.month.toString().padLeft(2, '0');
  return '$day/$month/${date.year}';
}

/// INTERVALO DE DATA's own 3 choices (spec-5-2; `prototype-extract.md`) —
/// each computes its own `dateFrom`/`dateTo` pair via [rangeFrom]. [allTime]
/// is itself a selectable choice meaning "no date filter at all", not some
/// maximal range — it resolves to `(null, null)`.
///
/// Lives in the domain layer (RNF06) rather than alongside
/// `EntriesFilterSheet` so `MeusRegistrosCubit` can store the selected
/// preset directly (code-review fix: re-deriving it from `dateFrom` by
/// equality match against a freshly recomputed "today" boundary goes stale
/// the moment a day/week/month boundary rolls over while the filter stays
/// active) without the cubit importing a presentation-layer widget file.
/// UI-facing copy (`label`) stays out of this enum, same split
/// `EntrySource`/`entrySourceLabel` already uses — see
/// `entries_filter_sheet.dart`'s own `dateRangePresetLabel`.
enum DateRangePreset {
  allTime,
  thisWeek,
  thisMonth;

  /// This preset's own `(dateFrom, dateTo)` pair, anchored to [now] (a
  /// parameter only so a test can pin it — every real call site passes
  /// `DateTime.now()`). `dateTo` is always [now] itself — "through right
  /// now" — `docs/input/` is silent on inclusive/exclusive bounds here
  /// (AGENTS.md policy: "decide and proceed"). `dateFrom` is local
  /// midnight of the Monday starting this week, or the 1st of this
  /// calendar month.
  (DateTime?, DateTime?) rangeFrom(DateTime now) {
    final today = DateTime(now.year, now.month, now.day);
    switch (this) {
      case DateRangePreset.allTime:
        return (null, null);
      case DateRangePreset.thisWeek:
        return (today.subtract(Duration(days: today.weekday - 1)), now);
      case DateRangePreset.thisMonth:
        return (DateTime(today.year, today.month), now);
    }
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

import '../../../../core/design_tokens.dart';
import '../../../../core/widgets/app_button.dart';
import '../../domain/entities/date_range_preset.dart';
import '../../domain/entities/entry.dart';
import '../cubit/meus_registros_cubit.dart';

/// TIPO DE ENTRADA's own label for each [EntrySource]
/// (`prototype-extract.md` Tela 4 — Sheet de filtro) — shared by this
/// sheet's own chips and `MeusRegistrosScreen`'s active-filter chip row,
/// so the two surfaces never drift out of sync with each other (Code Map).
String entrySourceLabel(EntrySource source) => switch (source) {
  EntrySource.manual => 'Manual',
  EntrySource.audio => 'Áudio',
  EntrySource.photo => 'Foto',
  EntrySource.chat => 'Chat',
};

/// [DateRangePreset]'s own UI copy — kept out of the domain enum itself,
/// same split [entrySourceLabel] already gives [EntrySource]; shared by
/// this sheet's own chips and `MeusRegistrosScreen`'s active-filter chip
/// row.
String dateRangePresetLabel(DateRangePreset preset) => switch (preset) {
  DateRangePreset.allTime => 'Todo o período',
  DateRangePreset.thisWeek => 'Esta semana',
  DateRangePreset.thisMonth => 'Este mês',
};

/// The filter bottom sheet (spec-5-2) — two single-choice groups
/// ("INTERVALO DE DATA", "TIPO DE ENTRADA"; Design Notes: no "CATEGORIA"
/// group — the backend has no category filter, RF06) plus "Aplicar"/
/// "Limpar". Mirrors `InsertionModal.show()`'s own bottom-sheet
/// choreography (`isScrollControlled`, `useSafeArea`, `colorScrimHeavy`, a
/// Reduce-Motion-aware `durationSheetUp` entrance) — Code Map.
class EntriesFilterSheet extends StatefulWidget {
  const EntriesFilterSheet({required this.cubit, super.key});

  /// Passed in directly rather than read via `context.read` (same
  /// rationale `InsertionModal`'s own cubit constructor params give): a
  /// `showModalBottomSheet` route's `builder` context is inserted above
  /// `MeusRegistrosScreen`'s own `MultiBlocProvider`, not below it, so
  /// nothing that `BlocProvider` exposes would be reachable from here
  /// anyway.
  final MeusRegistrosCubit cubit;

  /// Presents the sheet exactly as the class doc describes. [cubit]'s own
  /// `applyFilters()` is called directly by this sheet's "Aplicar" button
  /// (`_EntriesFilterSheetState._applyAndClose`) — this `static` method
  /// itself never touches the cubit.
  static Future<void> show(
    BuildContext context, {
    required MeusRegistrosCubit cubit,
  }) async {
    final reduceMotion = MediaQuery.of(context).disableAnimations;
    final controller =
        BottomSheet.createAnimationController(Navigator.of(context))
          ..duration = reduceMotion
              ? Duration.zero
              : DesignTokens.durationSheetUp
          ..reverseDuration = reduceMotion ? Duration.zero : null;
    try {
      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        barrierColor: DesignTokens.colorScrimHeavy,
        backgroundColor: Colors.transparent,
        elevation: 0,
        transitionAnimationController: controller,
        builder: (_) => EntriesFilterSheet(cubit: cubit),
      );
    } finally {
      // Same "wait for the exit animation before disposing the
      // controller" rationale as `InsertionModal.show()`'s own `finally`
      // block (see its doc for the full explanation) — disposing the
      // moment `showModalBottomSheet`'s own `Future` resolves would cut
      // the still-running reverse animation's ticker off mid-flight.
      if (!controller.isDismissed) {
        final animationDone = Completer<void>();
        void onStatusChange(AnimationStatus status) {
          if (status == AnimationStatus.dismissed) {
            animationDone.complete();
          }
        }

        controller.addStatusListener(onStatusChange);
        await animationDone.future;
        controller.removeStatusListener(onStatusChange);
      }
      controller.dispose();
    }
  }

  @override
  State<EntriesFilterSheet> createState() => _EntriesFilterSheetState();
}

class _EntriesFilterSheetState extends State<EntriesFilterSheet> {
  late EntrySource? _pendingSource;
  late DateRangePreset _pendingDateRange;

  @override
  void initState() {
    super.initState();
    // Pre-selects whichever filters are already active — `docs/input/` is
    // silent on this exact behavior (AGENTS.md policy: "decide and
    // proceed") — rather than always reopening blank, so reopening the
    // sheet to tweak just one filter doesn't silently discard the other.
    // Round-2 review fix: reads the cubit's own stored preset directly
    // rather than re-deriving it from `activeDateFrom` by equality match —
    // that re-derivation went stale (mis-pre-selecting "Todo o período")
    // the moment a day/week/month boundary rolled over while the filter
    // stayed active.
    _pendingSource = widget.cubit.activeSource;
    _pendingDateRange = widget.cubit.activeDateRangePreset;
  }

  void _applyAndClose() {
    final (dateFrom, dateTo) = _pendingDateRange.rangeFrom(DateTime.now());
    widget.cubit.applyFilters(
      source: _pendingSource,
      dateFrom: dateFrom,
      dateTo: dateTo,
      dateRangePreset: _pendingDateRange,
    );
    Navigator.of(context).pop();
  }

  /// "Limpar" (Boundaries: "resets only the sheet's own pending
  /// selection") — never touches [widget.cubit]/closes the sheet; that's
  /// `MeusRegistrosScreen`'s separate "Limpar filtros" link's own job
  /// (`MeusRegistrosCubit.clearFilters()`).
  void _clearPending() {
    setState(() {
      _pendingSource = null;
      _pendingDateRange = DateRangePreset.allTime;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: DesignTokens.screenPadding,
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(DesignTokens.radiusLg),
        ),
        boxShadow: DesignTokens.elevation2,
      ),
      child: SafeArea(
        top: false,
        // Epic-5 context's own UX note: "Filter chips and the search/
        // filter surfaces are a tight-fit area for Dynamic Type — verify
        // text does not truncate or clip at the largest accessibility
        // size" — a `SingleChildScrollView` guards against this sheet's
        // own content overflowing the screen at a large accessibility
        // text size, same safety net `InsertionModal`'s own tab content
        // already has (wrapped in its own `Flexible`/
        // `SingleChildScrollView` pair).
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                'INTERVALO DE DATA',
                style: DesignTokens.textMonoCaption.copyWith(
                  color: DesignTokens.colorTextSecondary,
                ),
              ),
              const SizedBox(height: DesignTokens.spacingSm),
              Wrap(
                spacing: DesignTokens.spacingSm,
                runSpacing: DesignTokens.spacingSm,
                children: [
                  for (final preset in DateRangePreset.values)
                    _FilterChip(
                      label: dateRangePresetLabel(preset),
                      selected: _pendingDateRange == preset,
                      onTap: () => setState(() => _pendingDateRange = preset),
                    ),
                ],
              ),
              const SizedBox(height: DesignTokens.spacingLg),
              Text(
                'TIPO DE ENTRADA',
                style: DesignTokens.textMonoCaption.copyWith(
                  color: DesignTokens.colorTextSecondary,
                ),
              ),
              const SizedBox(height: DesignTokens.spacingSm),
              Wrap(
                spacing: DesignTokens.spacingSm,
                runSpacing: DesignTokens.spacingSm,
                children: [
                  for (final source in EntrySource.values)
                    _FilterChip(
                      label: entrySourceLabel(source),
                      selected: _pendingSource == source,
                      // Single choice (Design Notes): unlike the date-range
                      // group above (whose 3 choices always include an
                      // explicit "none" — [DateRangePreset.allTime]),
                      // source has no dedicated "any source" chip — tapping
                      // the already-selected one toggles it back off
                      // instead of being a no-op, since that's otherwise
                      // the only way to clear just this one group without
                      // "Limpar" resetting the date group too.
                      onTap: () => setState(
                        () => _pendingSource = _pendingSource == source
                            ? null
                            : source,
                      ),
                    ),
                ],
              ),
              const SizedBox(height: DesignTokens.spacingLg),
              Row(
                children: [
                  Expanded(
                    child: AppButton(
                      label: 'Limpar',
                      variant: AppButtonVariant.textGhost,
                      onPressed: _clearPending,
                    ),
                  ),
                  const SizedBox(width: DesignTokens.spacingMd),
                  Expanded(
                    child: AppButton(
                      label: 'Aplicar',
                      onPressed: _applyAndClose,
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// One selectable group option — reused by both groups ("INTERVALO DE
/// DATA"/"TIPO DE ENTRADA"); selected state is `colorSecondary` fill +
/// `colorCategoryChipText` text, same token pair the active-filter chip
/// row (`MeusRegistrosScreen`) reuses for its own chips (Boundaries: exact
/// token reuse, no new token). Unselected state is a plain `colorBorder`
/// outline — not itself named by Boundaries, since only the *selected*
/// look is actually specified there.
class _FilterChip extends StatelessWidget {
  const _FilterChip({
    required this.label,
    required this.selected,
    required this.onTap,
  });

  final String label;
  final bool selected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      button: true,
      selected: selected,
      label: label,
      excludeSemantics: true,
      child: InkWell(
        borderRadius: const BorderRadius.all(
          Radius.circular(DesignTokens.radiusFull),
        ),
        onTap: onTap,
        child: Container(
          padding: const EdgeInsets.symmetric(
            horizontal: DesignTokens.spacingMd,
            vertical: DesignTokens.spacingSm,
          ),
          decoration: BoxDecoration(
            color: selected
                ? DesignTokens.colorSecondary
                : DesignTokens.colorSurfaceBg,
            borderRadius: const BorderRadius.all(
              Radius.circular(DesignTokens.radiusFull),
            ),
            border: selected
                ? null
                : Border.all(
                    color: DesignTokens.colorBorder,
                    width: DesignTokens.borderWidthDefault,
                  ),
          ),
          child: Text(
            label,
            style: DesignTokens.textLabelMd.copyWith(
              color: selected
                  ? DesignTokens.colorCategoryChipText
                  : DesignTokens.colorTextPrimary,
            ),
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';

import '../../../../core/design_tokens.dart';

/// `MeusRegistrosScreen`'s permanently-docked search bar (spec-5-1,
/// Acceptance Criteria: "permanently docked at the top of Meus Registros
/// with a trailing funnel icon and is never submitted via a button") —
/// paper-elevated like `EntryRecordCard` (`colorSurfaceElevated`,
/// `radiusMd`, `elevation1`). [onChanged] feeds
/// `EntriesSearchCubit.onQueryChanged` directly on every keystroke — there
/// is no submit button anywhere on this widget, by design (Boundaries).
///
/// spec-5-2: the trailing funnel (`Icons.filter_list`) button now opens
/// the filter sheet via [onFilterTap] (`MeusRegistrosScreen`'s own
/// `EntriesFilterSheet.show()` call replaces the former no-op
/// `onPressed: () {}`) — still sized to the shared 44pt minimum tap
/// target (`insertionModalTapTargetMin`, UX-DR23). [hasActiveFilters]
/// fills it (`colorPrimary` instead of the resting `colorTextSecondary`)
/// whenever any filter is active (Boundaries: "fills the funnel icon").
class EntriesSearchBar extends StatelessWidget {
  const EntriesSearchBar({
    required this.onChanged,
    required this.onFilterTap,
    this.hasActiveFilters = false,
    super.key,
  });

  final ValueChanged<String> onChanged;

  /// spec-5-2 — opens the filter sheet.
  final VoidCallback onFilterTap;

  /// spec-5-2 — `true` whenever `MeusRegistrosCubit.hasActiveFilters` is
  /// true; defaults `false` so this widget still renders sensibly for any
  /// caller that has no filter state of its own to report.
  final bool hasActiveFilters;

  @override
  Widget build(BuildContext context) {
    return DecoratedBox(
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        borderRadius: BorderRadius.all(Radius.circular(DesignTokens.radiusMd)),
        boxShadow: DesignTokens.elevation1,
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: DesignTokens.spacingMd),
        child: Row(
          children: [
            Expanded(
              child: TextField(
                onChanged: onChanged,
                style: DesignTokens.textBodyMd.copyWith(
                  color: DesignTokens.colorTextPrimary,
                ),
                decoration: InputDecoration(
                  isDense: true,
                  border: InputBorder.none,
                  hintText: 'Buscar nos registros...',
                  hintStyle: DesignTokens.textBodyMd.copyWith(
                    color: DesignTokens.colorTextSecondary,
                  ),
                  contentPadding: const EdgeInsets.symmetric(
                    vertical: DesignTokens.spacingMd,
                  ),
                ),
              ),
            ),
            SizedBox(
              width: DesignTokens.insertionModalTapTargetMin,
              height: DesignTokens.insertionModalTapTargetMin,
              child: IconButton(
                padding: EdgeInsets.zero,
                onPressed: onFilterTap,
                // Review finding: an unlabeled icon-only button gives a
                // screen-reader user no indication of its purpose.
                // Round-2 review fix: also distinguishes "filters active"
                // for a screen-reader user, who otherwise has no way to
                // learn that beyond separately discovering the chip row.
                tooltip: hasActiveFilters ? 'Filtros (ativos)' : 'Filtros',
                icon: Icon(
                  Icons.filter_list,
                  color: hasActiveFilters
                      ? DesignTokens.colorPrimary
                      : DesignTokens.colorTextSecondary,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

